<script setup lang="ts">
import { onMounted, reactive, ref } from 'vue'
import { buscarCuentasEgpNaturaleza, cambiarEstadoEgpNaturaleza, guardarPlantillaEgpNaturaleza, listarPlantillaEgpNaturaleza } from '../services/plantillaEgpNaturaleza'
import type { CuentaEgpNaturalezaOption, OpcionEgpNaturaleza, PlantillaEgpNaturaleza, PlantillaEgpNaturalezaPayload } from '../interfaces/plantillaEgpNaturaleza.interface'
const rows=ref<PlantillaEgpNaturaleza[]>([]),grupos=ref<OpcionEgpNaturaleza[]>([]),criterios=ref<OpcionEgpNaturaleza[]>([]),cuentas=ref<CuentaEgpNaturalezaOption[]>([]),criterio=ref(''),grupo=ref(''),consultaCuenta=ref(''),page=ref(1),lastPage=ref(1),total=ref(0),loading=ref(false),saving=ref(false),searching=ref(false),modal=ref(false),editing=ref<number|null>(null),error=ref(''),success=ref('')
const form=reactive<PlantillaEgpNaturalezaPayload>({codigogrupo:'',cuenta_contable_id:0,detalle:'',codigocriterio:'01',estado:true}),message=(v:unknown)=>v instanceof Error?v.message:'No se pudo completar la operación.'
async function load(next=1){loading.value=true;error.value='';try{const r=await listarPlantillaEgpNaturaleza(criterio.value,grupo.value,next);rows.value=r.data;grupos.value=r.grupos;criterios.value=r.criterios;page.value=r.current_page;lastPage.value=r.last_page;total.value=r.total}catch(v){error.value=message(v)}finally{loading.value=false}}
function open(item?:PlantillaEgpNaturaleza){editing.value=item?.id??null;Object.assign(form,{codigogrupo:item?.codigogrupo??'',cuenta_contable_id:item?.cuenta_contable_id??0,detalle:item?.detalle??'',codigocriterio:item?.codigocriterio??'01',estado:item?.estado??true});cuentas.value=item?.cuenta_contable?[item.cuenta_contable]:[];consultaCuenta.value=item?.cuenta_contable?`${item.cuenta_contable.cta_contable} - ${item.cuenta_contable.descripcion}`:'';error.value='';modal.value=true}
async function searchAccounts(){if(consultaCuenta.value.trim().length<2)return void(error.value='Ingrese al menos dos caracteres para buscar la cuenta.');searching.value=true;try{cuentas.value=await buscarCuentasEgpNaturaleza(consultaCuenta.value.trim())}catch(v){error.value=message(v)}finally{searching.value=false}}
async function save(){const detalle=form.detalle.trim();if(!form.codigogrupo||!form.codigocriterio||!form.cuenta_contable_id)return void(error.value='Complete el grupo, criterio y cuenta contable.');if(!detalle||detalle.length>100)return void(error.value='El detalle es obligatorio y admite hasta 100 caracteres.');saving.value=true;try{await guardarPlantillaEgpNaturaleza(editing.value,{...form,detalle:detalle.toUpperCase()});modal.value=false;success.value=`Cuenta ${editing.value?'actualizada':'agregada'} correctamente.`;await load(editing.value?page.value:1)}catch(v){error.value=message(v)}finally{saving.value=false}}
async function toggle(item:PlantillaEgpNaturaleza){if(!confirm(`¿Desea ${item.estado?'desactivar':'activar'} esta cuenta?`))return;try{await cambiarEstadoEgpNaturaleza(item.id);success.value='Estado actualizado correctamente.';await load(page.value)}catch(v){error.value=message(v)}}
onMounted(()=>load())
</script>
<template><div class="page"><nav><RouterLink to="/inicio">Inicio</RouterLink> / <RouterLink to="/modulos/administracion/contabilidad/proceso-contable">Proceso contable</RouterLink> / Plantilla E.G.P. por naturaleza</nav><header class="hero"><div class="mark">PN</div><div><small>MIA · CONTABILIDAD · PROCESO</small><h1>Plantilla E.G.P. por naturaleza</h1><p>Configura cuentas y criterios para los resultados financieros por naturaleza.</p></div><strong>{{total}} registros</strong><button @click="open()">+ Nueva cuenta</button></header><p v-if="success" class="flash success">✓ {{success}}</p><p v-if="error" class="flash error">{{error}}</p><form class="filters" @submit.prevent="load(1)"><input v-model.trim="criterio" placeholder="Buscar por cuenta o descripción"><select v-model="grupo"><option value="">Todos los grupos</option><option v-for="g in grupos" :key="g.codigo" :value="g.codigo">{{g.codigo}} - {{g.nombre}}</option></select><button>Buscar</button><button type="button" class="soft" @click="criterio='';grupo='';load(1)">Limpiar</button></form><section class="table-card"><div v-if="loading" class="empty">Consultando plantilla…</div><div v-else-if="!rows.length" class="empty">No se encontraron cuentas en la plantilla.</div><div v-else class="scroll"><table><thead><tr><th>ID</th><th>Grupo</th><th>Detalle</th><th>Cuenta contable</th><th>Criterio</th><th>Estado</th><th>Acciones</th></tr></thead><tbody><tr v-for="item in rows" :key="item.id"><td>#{{item.id}}</td><td><span class="tag">{{item.codigogrupo}} - {{item.codigogrupo_label}}</span></td><td>{{item.detalle}}</td><td><template v-if="item.cuenta_contable"><b>{{item.cuenta_contable.cta_contable}}</b> - {{item.cuenta_contable.descripcion}}</template><i v-else>Cuenta no disponible</i></td><td><span :class="item.codigocriterio==='01'?'ok':'bad'">{{item.codigocriterio_label}}</span></td><td><span :class="item.estado?'ok':'bad'">{{item.estado?'Activo':'Inactivo'}}</span></td><td class="actions"><button class="edit" @click="open(item)">Editar</button><button class="soft" @click="toggle(item)">{{item.estado?'Desactivar':'Activar'}}</button></td></tr></tbody></table></div><footer v-if="lastPage>1"><button :disabled="page<=1" @click="load(page-1)">Anterior</button><span>{{page}} / {{lastPage}}</span><button :disabled="page>=lastPage" @click="load(page+1)">Siguiente</button></footer></section><div v-if="modal" class="backdrop" @mousedown.self="modal=false"><form class="dialog" @submit.prevent="save"><header><div><small>PROCESO CONTABLE</small><h2>{{editing?'Editar':'Nueva'}} cuenta por naturaleza</h2></div><button type="button" @click="modal=false">×</button></header><div class="columns"><label>Grupo E.G.P. *<select v-model="form.codigogrupo"><option value="">Seleccione</option><option v-for="g in grupos" :key="g.codigo" :value="g.codigo">{{g.codigo}} - {{g.nombre}}</option></select></label><label>Criterio *<select v-model="form.codigocriterio"><option v-for="c in criterios" :key="c.codigo" :value="c.codigo">{{c.nombre}}</option></select></label></div><label>Buscar cuenta (máximo 3 dígitos) *<div class="search-account"><input v-model="consultaCuenta" @keydown.enter.prevent="searchAccounts"><button type="button" @click="searchAccounts">{{searching?'…':'Buscar'}}</button></div></label><label>Cuenta encontrada *<select v-model.number="form.cuenta_contable_id"><option :value="0">Seleccione</option><option v-for="c in cuentas" :key="c.id" :value="c.id">{{c.cta_contable}} - {{c.descripcion}}</option></select></label><label>Detalle *<input v-model="form.detalle" maxlength="100" @input="form.detalle=form.detalle.toUpperCase()"></label><label class="check"><input v-model="form.estado" type="checkbox"> Activo</label><footer><button type="button" class="soft" @click="modal=false">Cancelar</button><button :disabled="saving">{{saving?'Guardando…':'Guardar'}}</button></footer></form></div></div></template>
<style scoped>
.page{--a:#607b91;color:#35464e}nav{margin-bottom:16px;color:#929fa5;font-size:.68rem}nav a{color:var(--a);text-decoration:none}.hero{padding:20px;display:flex;align-items:center;gap:14px;border-left:5px solid var(--a);border-radius:12px;background:#fff}.mark{width:48px;height:48px;display:grid;place-items:center;border-radius:10px;color:#fff;background:var(--a);font-weight:800}.hero>div:nth-child(2){flex:1}.hero small{color:var(--a);font-size:.48rem;font-weight:800}.hero h1{margin:2px 0;font-size:1.3rem}.hero p{margin:0;color:#7e8a90;font-size:.67rem}.hero>strong{font-size:.55rem}button{padding:9px 12px;border:0;border-radius:6px;color:#fff;background:var(--a);font-size:.52rem}.flash{padding:9px}.success{color:#26704f;background:#eaf8f1}.error{color:#a64046;background:#fff0f0}.filters{margin-top:12px;padding:12px;display:grid;grid-template-columns:2fr 1fr auto auto;gap:7px;background:#fff}input,select{min-width:0;padding:9px;border:1px solid #d7dfe2;border-radius:6px;background:#fff;font:inherit;font-size:.52rem}.soft{color:#64727a!important;background:#edf1f3!important}.table-card{margin-top:12px;background:#fff}.empty{padding:45px;text-align:center}.scroll{overflow:auto}table{width:100%;min-width:1000px;border-collapse:collapse;font-size:.49rem}th,td{padding:8px;border:1px solid #e1e7ea;text-align:left}thead{color:#fff;background:#354a55}.tag,.ok,.bad{display:inline-block;padding:3px 7px;border-radius:10px;font-size:.44rem}.tag{color:#246579;background:#dff1f5}.ok{color:#277153;background:#def3e8}.bad{color:#9b4048;background:#f8dfe1}.actions{display:flex;gap:5px}.edit{color:#396c9f;background:#e5eef8}.table-card>footer{padding:10px;display:flex;justify-content:center;align-items:center;gap:10px;font-size:.52rem}.backdrop{position:fixed;inset:0;z-index:50;display:grid;place-items:center;padding:20px;background:#26343daa}.dialog{width:min(650px,100%);padding:18px;display:grid;gap:11px;border-radius:12px;background:#fff}.dialog>header{display:flex;justify-content:space-between}.dialog h2{margin:2px 0;font-size:1rem}.dialog>header button{padding:2px 8px;color:#65747a;background:#edf1f3;font-size:1rem}.dialog label{display:grid;gap:5px;font-size:.51rem}.columns{display:grid;grid-template-columns:1fr 1fr;gap:8px}.check{display:flex!important;align-items:center}.check input{width:auto}.dialog>footer{display:flex;justify-content:flex-end;gap:6px}.search-account{display:grid;grid-template-columns:1fr auto;gap:6px}@media(max-width:700px){.hero{flex-wrap:wrap}.filters,.columns{grid-template-columns:1fr}}
</style>
